using namespace tigersheets;
namespace {
void require(bool value,const std::string& message){if(!value)throw std::runtime_error(message);}
void near(double value,double expected,const std::string& message){require(std::abs(value-expected)<1e-6,message);}
Json at(int row,int col=2,const std::string& sheet="model"){return {{"sheet",sheet},{"row",row},{"col",col}};}
Json input(int row,const Json& value,const std::string& type="number"){auto result=at(row);result["type"]=type;result["value"]=value;return result;}
Json destination(const std::string& sheet){return {{"sheet",sheet},{"row1",1},{"col1",1}};}
const Json& sheet(const Json& book,const std::string& id){for(const auto& candidate:book.at("sheets"))if(candidate.at("id")==id)return candidate;throw std::runtime_error("missing sheet "+id);}
const Json& model(const Json& book,const std::string& id){for(const auto& candidate:book.at("financialModels"))if(candidate.at("id")==id)return candidate;throw std::runtime_error("missing model "+id);}
double number(const Json& calculation,const std::string& sheet,int row,int col=2){for(const auto& value:calculation.at("values"))if(value.at("sheet")==sheet&&value.at("row")==row&&value.at("col")==col){require(value.at("type")=="number","expected numeric calculated cell");return value.at("value");}throw std::runtime_error("missing calculated value");}
Json initialBook(){Json cells=Json::array();const auto put=[&](int row,int col,const std::string& value,const Json& style=Json::object()){cells.push_back({{"row",row},{"col",col},{"input",value},{"style",style}});};put(1,1,"Forecast workflow acceptance",{{"bold",true}});for(const auto& entry:std::vector<std::pair<int,std::string>>{{2,"Revenue"},{3,"Growth"},{4,"Margin"},{5,"Expense"},{6,"Account code"},{7,"Approved"},{8,"Optional input"},{10,"Next revenue"},{11,"Profit"}})put(entry.first,1,entry.second);put(2,2,"1000",{{"numberFormat","$#,##0.00"}});put(3,2,"0.1",{{"numberFormat","0.0%"}});put(4,2,"0.2",{{"numberFormat","0.0%"}});put(5,2,"100",{{"numberFormat","$#,##0.00"}});put(6,2,"'00123");put(7,2,"TRUE");put(10,2,"=B2*(1+B3)",{{"numberFormat","$#,##0.00"}});put(11,2,"=B10*B4-B5",{{"numberFormat","$#,##0.00"}});Json sheets=Json::array({{{"id","model"},{"name","Operating model"},{"cells",cells}}});for(const auto& entry:std::vector<std::pair<std::string,std::string>>{{"forecast","Forecast"},{"comparison","Scenario comparison"},{"one","One variable"},{"two","Two variables"}})sheets.push_back({{"id",entry.first},{"name",entry.second},{"cells",Json::array()}});return {{"revision",0},{"sheets",sheets}};}
struct Workflow {
 WorkbookSession session{initialBook()};CalculationEngine engine;std::uint64_t generation=51;
 Json prepare(const Json& definition,const std::string& action="run"){const auto before=session.snapshot();CalculationContext context;context.snapshot=before;context.generation=generation;context.evaluator=[this](const Json& candidate){return engine.calculate(candidate);};const auto result=executeFinancialWorkflow(before,definition,action,context);require(session.snapshotView()==before&&context.snapshot==before,"workflow preparation preserves live inputs and immutable calculation context");require(result.at("revision")==before.at("revision")&&result.at("contextGeneration")==generation,"workflow result retains its prepared epoch");require(result.at("analysis").value("success",false),result.at("analysis").dump());return result;}
 void apply(const Json& result){std::string error;require(session.apply(session.snapshotView().at("revision"),result.at("operations"),&error),error);}
 Json run(const Json& definition,const std::string& action="run"){auto result=prepare(definition,action);apply(result);return result;}
};
}
int main(){try{
 Workflow workflow;auto& session=workflow.session;const auto source=sheet(session.snapshotView(),"model");
 const Json baseline={{"version",1},{"id","base"},{"name","Base assumptions"},{"kind","assumption_set"},{"cells",Json::array({input(2,1000),input(3,0.1),input(4,0.2),input(6,"00123","string"),input(7,true,"boolean"),input(8,nullptr,"blank")})}};
 const Json upside={{"version",1},{"id","up"},{"name","Upside"},{"kind","scenario"},{"cells",Json::array({input(2,1200),input(3,0.2),input(4,0.25)})}};
 workflow.run(baseline,"save");workflow.run(upside,"save");require(sheet(session.snapshotView(),"model")==source,"saving assumption sets never applies input values");
 const auto beforeApply=session.snapshot();workflow.run(upside,"apply");near(number(workflow.engine.calculate(session.snapshotView()),"model",11),260,"applying Upside produces profit260");require(session.undo(),"scenario application is undoable");require(session.snapshotView().at("sheets")==beforeApply.at("sheets")&&session.snapshotView().at("financialModels")==beforeApply.at("financialModels"),"one undo restores source inputs and saved definitions");
 Json forecast={{"version",1},{"id","revenue-forecast"},{"name","Revenue and cost forecast"},{"kind","forecast"},{"periods",3},{"startPeriod",2027},{"drivers",Json::array({{{"name","Revenue"},{"base",at(2)},{"growth",at(3)},{"numberFormat","$#,##0.00"}},{{"name","Costs"},{"base",100},{"growth",0.05},{"numberFormat","$#,##0.00"}}})},{"output",destination("forecast")}};
 const auto report=workflow.prepare(forecast);require(sheet(session.snapshotView(),"forecast").at("cells").empty(),"unaccepted preview leaves destination empty");workflow.apply(report);const auto forecastCells=sheet(session.snapshotView(),"forecast").at("cells");near(model(session.snapshotView(),"revenue-forecast").at("results")[0][2],1331,"forecast compounds independently known revenue");require(session.undo()&&sheet(session.snapshotView(),"forecast").at("cells").empty(),"one undo removes generated cells and saved report");require(session.redo()&&sheet(session.snapshotView(),"forecast").at("cells")==forecastCells,"redo restores complete forecast ownership and formulas");
 auto profit=at(11);profit["label"]="Profit";profit["numberFormat"]="$#,##0.00";auto revenue=at(10);revenue["label"]="Revenue";revenue["numberFormat"]="$#,##0.00";const Json comparison={{"version",1},{"id","cases"},{"name","Profit by scenario"},{"kind","scenario_comparison"},{"scenarioIds",Json::array({"base","up"})},{"outputs",Json::array({profit,revenue})},{"includeBaseline",true},{"output",destination("comparison")}};workflow.run(comparison);const auto& cases=model(session.snapshotView(),"cases").at("results");near(cases[0][0],120,"current profit120");near(cases[1][0],120,"base profit120");near(cases[2][0],260,"upside profit260 without accumulated scenario edits");
 auto margin=at(4);margin["values"]=Json::array({0.1,0.2,0.3});margin["numberFormat"]="0.0%";Json sensitivity={{"version",1},{"id","margin-sensitivity"},{"name","Margin sensitivity"},{"kind","sensitivity"},{"inputs",Json::array({margin})},{"result",profit},{"output",destination("one")}};workflow.run(sensitivity);const auto& one=model(session.snapshotView(),"margin-sensitivity").at("results");near(one[0][0],10,"margin10percent profit10");near(one[1][0],120,"margin20percent profit120");near(one[2][0],230,"margin30percent profit230");
 auto growth=at(3);growth["values"]=Json::array({0,0.1});growth["numberFormat"]="0.0%";sensitivity["id"]="two-input-sensitivity";sensitivity["name"]="Margin and growth sensitivity";sensitivity["inputs"]=Json::array({margin,growth});sensitivity["output"]=destination("two");workflow.run(sensitivity);const auto& two=model(session.snapshotView(),"two-input-sensitivity").at("results");near(two[0][0],0,"two axis low margin zero growth");near(two[0][2],200,"two axis high margin zero growth");near(two[1][2],230,"two axis high margin positive growth");require(sheet(session.snapshotView(),"model")==source,"all report previews leave original source cells and formats unchanged");
 Json goal={{"version",1},{"id","profit-target"},{"name","Profit target 200"},{"kind","goal_seek"},{"specification",{{"output",at(11)},{"changing",at(4)},{"target",200},{"lower",0},{"upper",1},{"tolerance",1e-9},{"maxIterations",100},{"maxEvaluations",200}}}};workflow.run(goal,"save");const auto beforeGoal=session.snapshot();const auto sought=workflow.run(goal);near(sought.at("analysis").at("value"),3.0/11,"Goal Seek solves margin3over11");near(number(workflow.engine.calculate(session.snapshotView()),"model",11),200,"accepted Goal Seek matches requested profit");require(session.undo()&&session.snapshotView().at("sheets")==beforeGoal.at("sheets"),"Goal Seek edits and setup update undo as one change");
 auto variable=at(4);variable.update({{"lower",0},{"upper",0.5},{"start",0.2},{"integer",false},{"binary",false}});auto constraint=at(11);constraint.update({{"relation","<="},{"value",300}});const Json solver={{"version",1},{"id","profit-solver"},{"name","Profit with cap"},{"kind","solver"},{"specification",{{"objective",at(11)},{"goal","max"},{"method","linear"},{"variables",Json::array({variable})},{"constraints",Json::array({constraint})},{"tolerance",1e-7},{"maxEvaluations",10000},{"seed",42}}}};workflow.run(solver,"save");const auto beforeSolver=session.snapshot();const auto solved=workflow.run(solver);require(solved.at("analysis").at("success"),"linear Solver returns qualified success");near(number(workflow.engine.calculate(session.snapshotView()),"model",11),300,"bounded linear Solver reaches independently known cap");require(session.undo()&&session.snapshotView().at("sheets")==beforeSolver.at("sheets"),"one undo restores Solver changing inputs while retaining saved setup");
 const auto example=workflow.prepare({{"kind","example"}},"example");workflow.apply(example);const auto calculated=workflow.engine.calculate(session.snapshotView());require(calculated.at("status")=="ok"&&calculated.value("iteration",Json::object()).value("converged",true),"circular financing converges before publication");near(number(calculated,"circular-financing",6),50.0/0.9,"debt funding converges to55.5556");near(number(calculated,"circular-financing",7),50.0/9,"interest expense converges to5.5556");require(sheet(session.snapshotView(),"model")==source,"numerical workflows and circular example preserve original source model");
 char temporary[]="/tmp/tigersheets-financial-acceptance-XXXXXX";const auto* configured=std::getenv("TIGERSHEETS_FINANCIAL_FIXTURE_DIR");const auto* path=configured?configured:mkdtemp(temporary);require(path,"fixture directory");const std::filesystem::path directory(path);std::filesystem::create_directories(directory);const auto first=directory/"financial-workflows.xlsx",second=directory/"financial-workflows-resaved.xlsx";writeWorkbook(first.string(),session.snapshotView());auto reopened=readWorkbook(first.string());require(reopened.workbook.at("financialModels")==session.snapshotView().at("financialModels"),"all seven workflow kinds and typed setups survive first native save/reopen");WorkbookSession secondSession(reopened.workbook);std::string error;require(secondSession.apply(secondSession.snapshotView().at("revision"),Json::array({{{"type","set_cell"},{"sheet","model"},{"row",13},{"col",1},{"input","Two native save cycles checked"}}}),&error),error);writeWorkbook(second.string(),secondSession.snapshotView(),&reopened);const auto again=readWorkbook(second.string());require(again.workbook.at("financialModels")==secondSession.snapshotView().at("financialModels"),"all saved definitions and caches survive a second edited native save/reopen");WorkbookSession roundtrip(again.workbook);require(roundtrip.cellAt("forecast",2,6)->at("financialModelOwner")=="revenue-forecast","reopened auditable formulas retain generated ownership");require(!roundtrip.apply(roundtrip.snapshotView().at("revision"),Json::array({{{"type","set_cell"},{"sheet","forecast"},{"row",2},{"col",6},{"input","999"}}}),&error),"reopened report formulas refuse direct overwrite");near(number(workflow.engine.calculate(again.workbook),"model",11),120,"source model calculates unchanged after two save cycles");
 Json summary={{"status","passed"},{"files",Json::array({first.filename().string(),second.filename().string()})},{"financialModels",again.workbook.at("financialModels").size()},{"sourcePreserved",true},{"previewBeforeApply",true},{"undoRedo",true},{"saveCycles",2},{"excelApplicationVerified",false}};std::ofstream(directory/"acceptance-summary.json")<<summary.dump(2)<<'\n';if(!configured)std::filesystem::remove_all(directory);std::cout<<summary.dump()<<'\n';return 0;
}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
